output_text:
[
  {
    "id": "take_cart_at_start",
    "text": "A shopper is obliged to take the available cart from the entrance cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_station": "at(1,5)",
        "cart_waiting_at_station": "cartAt(1,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_cart_station",
              "cart_waiting_at_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "A shopper is prohibited from carrying groceries by hand or picking up an item without already having the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the designated cart-return bay before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "at_cart_station": "at(1,5)",
        "cart_waiting_at_station": "cartAt(1,5)",
        "pushing_cart": "hasCart",
        "at_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "at_cart_station",
              "cart_waiting_at_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "at_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_bay",
    "text": "Putting the cart down is prohibited unless the shopper is at the designated cart-return bay.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "leave_cart_somewhere": {
          "pre": {
            "and": [
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_somewhere",
          {
            "not": "at_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_before_cart_return",
    "text": "A shopper is prohibited from exiting the store while still pushing the cart or before the cart is parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "or": [
              "pushing_cart",
              {
                "not": "cart_parked_in_return_bay"
              }
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_interactions_after_return",
    "text": "Once the cart is parked in the return bay, further object interactions are prohibited; the shopper should only walk to the exit.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_parked_in_return_bay",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "no_carts_in_exit_zone",
    "text": "Carts are prohibited in the checkout and exit-side zone of the store, so the shopper must park the cart before entering that area.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "exit_zone": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushing_cart",
          "exit_zone"
        ]
      }
    }
  },
  {
    "id": "must_drop_cart_at_bay",
    "text": "When a shopper reaches the return bay while pushing the cart, moving away with the cart is prohibited; the next interaction should be leaving the cart there.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "move_away_from_return_bay_with_cart": {
          "pre": {
            "and": [
              "at_return_bay",
              "pushing_cart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_from_return_bay_with_cart"
    }
  }
]
